  },
  headerKicker: {
    fontSize: typography.fontSizeCaption,
    fontWeight: typography.fontWeightSemibold,
    color: colors.colorTextSecondary,
    textTransform: 'uppercase',
  },
  headerTitle: {
    fontSize: typography.fontSizeH3,
    fontWeight: typography.fontWeightSemibold,
    lineHeight: typography.lineHeightH3,
    color: colors.colorTextPrimary,
  },
  headerMeta: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    marginTop: spacing.xs,
  },
  metaChip: {
    backgroundColor: colors.colorBgMuted,
    borderRadius: radius.full,
    paddingHorizontal: spacing.sm,
    paddingVertical: 2,
  },
  metaChipPreview: {
    backgroundColor: colors.colorInfoSubtle,
    borderRadius: radius.full,
    paddingHorizontal: spacing.sm,
    paddingVertical: 2,
  },
  infoContainer: {
    paddingHorizontal: spacing.pagePadding,
    paddingBottom: spacing.xl,
    gap: spacing.lg,
  },
  courseContext: {
    gap: spacing.xs,
  },
  coursePressable: {
    gap: spacing.xs,
  },
  courseTitle: {
    fontSize: typography.fontSizeBody,
    fontWeight: typography.fontWeightSemibold,
    color: colors.colorTextPrimary,
  },
  actionsRow: {
    flexDirection: 'row',
    gap: spacing.sm,
  },
  navButton: {
    flex: 1,
  },
  sectionLabel: {
    fontSize: typography.fontSizeCaption,
    fontWeight: typography.fontWeightSemibold,
    color: colors.colorTextSecondary,
    textTransform: 'uppercase',
    marginBottom: spacing.xs,
  },
  descriptionSection: {
    gap: spacing.xs,
  },
  descriptionText: {
    fontSize: typography.fontSizeBody,
    lineHeight: typography.lineHeightBody,
    color: colors.colorTextSecondary,
  },
  lessonProgress: {
    fontSize: typography.fontSizeCaption,
    fontWeight: typography.fontWeightSemibold,
    color: colors.colorTextTertiary,
    marginTop: spacing.xs,
  },
  sheetBackdrop: {
    flex: 1,
    backgroundColor: colors.colorOverlay,
    justifyContent: 'flex-end',
  },
  sheet: {
    backgroundColor: colors.colorBgSurface,
    borderTopLeftRadius: radius.sheet,
    borderTopRightRadius: radius.sheet,
    paddingBottom: spacing.xl,
    maxHeight: '85%',
  },
  sheetHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: spacing.pagePadding,
    paddingTop: spacing.lg,
    paddingBottom: spacing.md,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: colors.colorBorder,
  },
  sheetClose: {
    width: 48,
    height: 48,
    alignItems: 'center',
    justifyContent: 'center',
  },
  sheetListContent: {
    paddingHorizontal: spacing.pagePadding,
    paddingTop: spacing.sm,
    paddingBottom: spacing.lg,
  },
  sheetSection: {
    marginTop: spacing.md,
    marginBottom: spacing.xs,
  },
  sheetRow: {
    minHeight: 48,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    paddingVertical: spacing.sm,
    paddingHorizontal: spacing.sm,
    borderRadius: radius.control,
  },
  sheetRowActive: {
    backgroundColor: colors.colorPrimarySubtle,
  },
  sheetRowIndex: {
    width: 24,
    textAlign: 'center',
  },
  sheetRowText: {
    flex: 1,
  },
});

